/// [blocks] with every text block cleaned, or `null` when none changed.
List<ContentBlock>? _stripTextBlocks(List<ContentBlock> blocks) {
  final cleaned = <ContentBlock>[];
  var firstText = true;
  var changed = false;
  for (final block in blocks) {
    if (block is! TextContent) {
      cleaned.add(block);
      continue;
